const data = {
  demoOnly: true,
  intakePackets: [
    { fakeClientId: 'FAKE-CLIENT-3001', preferredSchedule: 'weekday mornings', requestedServiceCategory: 'individual therapy demo category', payerCategory: 'commercial demo payer', preferredModality: 'telehealth' },
    { fakeClientId: 'FAKE-CLIENT-3002', preferredSchedule: 'evenings', requestedServiceCategory: 'couples therapy demo category', payerCategory: 'private pay demo', preferredModality: 'in person' }
  ],
  clinicians: [
    { clinicianId: 'DEMO-CLIN-01', name: 'Demo Clinician One', availability: 'weekday mornings', modalities: ['telehealth', 'in person'], serviceCategories: ['individual therapy demo category'] },
    { clinicianId: 'DEMO-CLIN-02', name: 'Demo Clinician Two', availability: 'evenings', modalities: ['in person'], serviceCategories: ['couples therapy demo category'] }
  ]
};
return [{ json: data }];

if ($json.demoOnly !== true) {
  throw new Error('Demo guard blocked execution. This simulated workflow accepts fake data only.');
}
return [{ json: { ...$json, guard: 'passed-fake-data-only' } }];

const clinicians = $json.clinicians;
const routed = $json.intakePackets.map((packet) => {
  const match = clinicians.find((clinician) => clinician.availability === packet.preferredSchedule && clinician.modalities.includes(packet.preferredModality) && clinician.serviceCategories.includes(packet.requestedServiceCategory));
  return {
    ...packet,
    matchedClinician: match ? match.name : 'manual review required',
    nextStep: match ? 'demo handoff packet ready' : 'demo routing review',
    productionWarning: 'Requires BAA, insurance, hosting, vendor approvals, risk analysis, and retention policy before real use.'
  };
});
return routed.map((item) => ({ json: item }));
